import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { PLATFORM_VERSION } from '../constants.js';
import { isTestOrSandboxAccount } from '../utils.js';
import { loadFunctionInfo } from './config.js';
import { resolveAccessTokenKey } from './constants.js';
import { buildContext } from './context.js';
import { ExecutionError, PrivateAppUserTokenUnavailableError, Reason, } from './errors.js';
import { loadSecrets, setProperTokenInSecrets } from './secrets.js';
import { diffLists, formatSeconds, throwUnhandledPlatformVersionError, } from './utils.js';
const require = createRequire(import.meta.url);
export async function executeFunction(config, functionName, localExecutionInputs, callback, privateAppUserTokenManager) {
    const { logger } = config;
    const { appId } = localExecutionInputs;
    if (config.platformVersion === PLATFORM_VERSION.V20252) {
        throw new ExecutionError({
            reason: Reason.UnsupportedVersion,
            functionName,
        });
    }
    const accessTokenKey = resolveAccessTokenKey(config.platformVersion);
    const functionInfo = loadFunctionInfo(config, functionName, appId);
    const functionPath = path.isAbsolute(functionInfo.file)
        ? functionInfo.file
        : path.resolve(path.join(functionInfo.srcDir, functionInfo.file));
    if (!fs.existsSync(functionPath)) {
        logger.error(`Could not find file ${functionPath}.`);
        throw new ExecutionError({
            reason: Reason.FunctionNotFound,
            functionName,
            appId,
        });
    }
    delete require.cache[require.resolve(functionPath)];
    let main;
    try {
        ({ main } = require(functionPath));
    }
    catch (error) {
        const errMessage = error instanceof Error ? error.message : String(error);
        logger.error(`App function failed to load: ${errMessage}`);
        throw new ExecutionError({
            reason: Reason.UncaughtError,
            functionName,
            cause: error,
        });
    }
    if (!main) {
        logger.error(`Could not find "main" export in ${functionPath}.`);
        throw new ExecutionError({
            reason: Reason.InvalidFunction,
            functionName,
        });
    }
    const savedEnv = { ...process.env };
    const initialSecrets = loadSecrets(functionInfo.srcDir, accessTokenKey);
    // app token from the env file
    const privateAppToken = process.env[accessTokenKey];
    const skipUserToken = await isTestOrSandboxAccount(config.accountId);
    // For sandbox/test accounts that can't mint tokens via localdevauth, get
    // the access token derived from the PAK in config.yml if available.
    if (skipUserToken && !privateAppToken) {
        try {
            const { accessTokenForPersonalAccessKey } = await import('@hubspot/local-dev-lib/personalAccessKey');
            const configToken = await accessTokenForPersonalAccessKey(config.accountId);
            if (configToken) {
                if (initialSecrets) {
                    initialSecrets[accessTokenKey] = configToken;
                }
                process.env[accessTokenKey] = configToken;
            }
        }
        catch {
            // No config token available — will fall through to throwing getter
        }
    }
    // fetch the user token from the local dev service
    const privateAppUserToken = 
    // don't attempt to fetch tokens except for standard accounts
    !skipUserToken && typeof appId === 'number'
        ? await privateAppUserTokenManager?.getPrivateAppUserToken(appId, {
            privateAppToken,
            accessTokenKey,
        })
        : undefined;
    const secrets = setProperTokenInSecrets(initialSecrets, logger, privateAppUserToken, {
        accountId: config.accountId,
        installThrowingGetter: skipUserToken && !process.env[accessTokenKey],
        accessTokenKey,
    });
    const { deleted: missingSecrets } = diffLists(
    // secrets expected
    functionInfo.secrets ?? [], 
    // secrets available
    Object.keys(process.env));
    if (missingSecrets.length > 0) {
        logger.warn(`The following required secrets are missing: ${missingSecrets}. Please supply them as environment variables for local execution in a .env file.`);
    }
    let context;
    try {
        context = await buildContext(config, localExecutionInputs, secrets);
    }
    catch (err) {
        process.env = savedEnv;
        throw err;
    }
    // eslint-disable-next-line no-async-promise-executor
    const rawResponse = await new Promise(async (resolve, reject) => {
        // Start the timer to throw an error after 20s unless the timer
        // is unref'd after the function completes (even with error)
        const ms = config.functionTimeoutMs;
        const timeout = setTimeout(() => {
            process.env = savedEnv;
            logger.error(`App function failed to callback within ${formatSeconds(ms, 2)}.`);
            reject(new ExecutionError({
                reason: Reason.Timeout,
                functionName,
                elapsedTimeMs: ms,
            }));
        }, ms);
        // Catch any error thrown from the function, which may or may not be async
        try {
            switch (config.platformVersion) {
                case PLATFORM_VERSION.V20251:
                case PLATFORM_VERSION.V202603:
                case PLATFORM_VERSION.V202603BETA:
                case PLATFORM_VERSION.V202609:
                case PLATFORM_VERSION.V202609BETA:
                case PLATFORM_VERSION.V202703:
                case PLATFORM_VERSION.V202703BETA:
                case PLATFORM_VERSION.UNSTABLE: {
                    const response = await main(context);
                    clearTimeout(timeout);
                    process.env = savedEnv;
                    resolve(response);
                    break;
                }
                case PLATFORM_VERSION.V20252: {
                    clearTimeout(timeout);
                    process.env = savedEnv;
                    reject(new ExecutionError({
                        reason: Reason.UnsupportedVersion,
                        functionName,
                    }));
                    break;
                }
                default:
                    return throwUnhandledPlatformVersionError(config.platformVersion);
            }
        }
        catch (error) {
            clearTimeout(timeout);
            process.env = savedEnv;
            if (error instanceof PrivateAppUserTokenUnavailableError) {
                reject(error);
                return;
            }
            logger.error(`App function encountered an uncaught error.`, error);
            reject(new ExecutionError({
                reason: Reason.UncaughtError,
                functionName,
                cause: error,
            }));
        }
        finally {
            timeout.unref();
        }
    });
    // Confirm that the response is valid JSON
    let jsonResponse = null;
    try {
        jsonResponse =
            rawResponse === undefined
                ? null
                : JSON.parse(JSON.stringify(rawResponse));
    }
    catch (error) {
        logger.error(`App function response is not valid JSON.`);
        throw new ExecutionError({
            reason: Reason.InvalidResponse,
            functionName,
        });
    }
    callback(jsonResponse);
}
